+
+#include "diag.h"
+
+#import <LocalAuthentication/LocalAuthentication.h>
+#import <Security/Security.h>
+#import <Security/CodeSigning.h>
+
+int TouchIDDiag(int *hasSignatureOut, int *hasEntitlementsOut,
+                int *passedLAPolicyTestOut, int *passedSecureEnclaveTestOut) {
+  *hasSignatureOut = 0;
+  *hasEntitlementsOut = 0;
+  *passedLAPolicyTestOut = 0;
+  *passedSecureEnclaveTestOut = 0;
+
+  SecCodeRef code = NULL;
+  if (SecCodeCopySelf(kSecCSDefaultFlags, &code) == errSecSuccess && code) {
+    *hasSignatureOut =
+        SecCodeCheckValidity(code, kSecCSStrictValidate, NULL) == errSecSuccess;
+
+    CFDictionaryRef signingInfo = NULL;
+    if (SecCodeCopySigningInformation(code, kSecCSSigningInformation,
+                                      &signingInfo) == errSecSuccess &&
+        signingInfo) {
+      CFDictionaryRef entitlements = CFDictionaryGetValue(
+          signingInfo, kSecCodeInfoEntitlementsDict);
+      *hasEntitlementsOut = entitlements && CFDictionaryGetCount(entitlements) > 0;
+      CFRelease(signingInfo);
+    }
+    CFRelease(code);
+  }
+
+  LAContext *context = [[LAContext alloc] init];
+  NSError *policyError = nil;
+  *passedLAPolicyTestOut = [context
+      canEvaluatePolicy:LAPolicyDeviceOwnerAuthenticationWithBiometrics
+                  error:&policyError];
+
+  CFErrorRef accessError = NULL;
+  SecAccessControlRef access = SecAccessControlCreateWithFlags(
+      kCFAllocatorDefault, kSecAttrAccessibleWhenUnlockedThisDeviceOnly,
+      kSecAccessControlPrivateKeyUsage | kSecAccessControlBiometryAny,
+      &accessError);
+  if (accessError) {
+    CFRelease(accessError);
+  }
+  if (access) {
+    NSDictionary *attributes = @{
+      (id)kSecAttrKeyType : (id)kSecAttrKeyTypeECSECPrimeRandom,
+      (id)kSecAttrKeySizeInBits : @256,
+      (id)kSecAttrTokenID : (id)kSecAttrTokenIDSecureEnclave,
+      (id)kSecPrivateKeyAttrs : @{
+        (id)kSecAttrIsPermanent : @NO,
+        (id)kSecAttrAccessControl : (__bridge id)access,
+      },
+    };
+    CFErrorRef keyError = NULL;
+    SecKeyRef key = SecKeyCreateRandomKey(
+        (__bridge CFDictionaryRef)attributes, &keyError);
+    *passedSecureEnclaveTestOut = key != NULL;
+    if (key) {
+      CFRelease(key);
+    }
+    if (keyError) {
+      CFRelease(keyError);
+    }
+    CFRelease(access);
+  }
+
+  return 0;
+}
